import podiumData from "./podium.json";
import { CHK_BASE, KCHK_BASE } from "./players";
import { fixedPhoto } from "./winners";

// podium.json is generated by `npm run sync-podium` from imafia.org and mafgame.org.
export type TournamentFormat = "single" | "team" | "series";

export type PodiumResult = {
  nick: string;
  group: string;
  place: number;
  team: { name: string; place: number } | null;
  profileUrl: string | null;
};

export type PodiumTournament = {
  source: string;
  title: string;
  url: string;
  start: string;
  end: string;
  location: string;
  format: TournamentFormat;
  players: number;
  results: PodiumResult[];
};

export type PodiumFinish = {
  place: number;
  nick: string;
  photo?: string;
  tournament: PodiumTournament;
  team: string | null;
};

// The two-week period the results cover.
export const PODIUM_PERIOD: { start: string; end: string } = podiumData.period;
export const PODIUM_TOURNAMENTS = podiumData.tournaments as PodiumTournament[];

// Lowercased letters and digits only, so "Сью⚡️" matches "Сью" and "Мёд" matches "Мед"
// (the same rule as scripts/sync-podium.mjs).
function normalizeNick(nick: string) {
  return nick.normalize("NFKC").toLowerCase().replace(/ё/g, "е").replace(/[^\p{L}\p{N}]/gu, "");
}

const PHOTOS = new Map(
  [...CHK_BASE, ...KCHK_BASE]
    .filter((player) => player.photo)
    .map((player) => [normalizeNick(player.nick), player.photo]),
);

// By iMafia profile first (the club-approved photos are keyed by it), then by nick.
export function playerPhoto(nick: string, profileUrl?: string | null) {
  return (profileUrl && fixedPhoto(profileUrl)) || PHOTOS.get(normalizeNick(nick));
}

function isPrizePlace(place: number) {
  return place >= 1 && place <= 3;
}

// Top-three finishes: a personal place, or the team's place in a team tournament.
export function podiumFinishes(): PodiumFinish[] {
  const finishes: PodiumFinish[] = [];
  for (const tournament of PODIUM_TOURNAMENTS) {
    for (const result of tournament.results) {
      const base = { nick: result.nick, photo: playerPhoto(result.nick, result.profileUrl), tournament };
      if (isPrizePlace(result.place)) finishes.push({ ...base, place: result.place, team: null });
      if (result.team && isPrizePlace(result.team.place)) {
        finishes.push({ ...base, place: result.team.place, team: result.team.name });
      }
    }
  }
  return finishes.sort((a, b) => a.place - b.place);
}
